# S6 - webhook intermediate catch (HMAC, activation condition, messageId dedupe, early callback / TTL) + webhook start (API key).
# Usage: powershell -File run.ps1      (models are generated by `node gen.js`)
. "$PSScriptRoot\lib.ps1"
$IN = 'http://localhost:8086/inbound'
$SECRET = 's6-test-secret'
$run = (Get-Date).ToString('HHmmss')
foreach ($f in 's6-esign-ttl', 's6-esign-nottl', 's6-b2b-start') { Deploy-Bpmn "$PSScriptRoot\$f.bpmn" | Out-Null }

function Sign([string]$body) {
  $h = New-Object System.Security.Cryptography.HMACSHA256 (, [Text.Encoding]::UTF8.GetBytes($SECRET))
  -join ($h.ComputeHash([Text.Encoding]::UTF8.GetBytes($body)) | ForEach-Object { $_.ToString('x2') })
}
function Post([string]$path, [hashtable]$payload, [string]$sig = 'auto', [hashtable]$extra = @{}) {
  $body = $payload | ConvertTo-Json -Depth 10 -Compress
  $hd = @{}; foreach ($k in $extra.Keys) { $hd[$k] = $extra[$k] }
  if ($sig -eq 'auto') { $hd['X-Signature'] = Sign $body } elseif ($sig) { $hd['X-Signature'] = $sig }
  $r = Invoke-Http -Method POST -Url "$IN/$path" -Body $body -Headers $hd -NoAuth
  Write-Host ("  POST /inbound/{0} eventId={1} status={2} sig={3} -> HTTP {4} {5}" -f $path, $payload.eventId, $payload.status, $(if ($hd['X-Signature']) { $hd['X-Signature'].Substring(0, 8) + '..' } else { 'none' }), $r.Status, $r.Raw)
  return $r
}
function Evt($env, $eid, $status = 'COMPLETED') { @{ eventId = $eid; envelopeId = $env; status = $status; signedAt = '2026-10-31T10:00:00Z'; signer = @{ name = 'Ada Lovelace' } } }
function Wait-Webhook([string]$ctx) {
  # wait until the connectors runtime has activated the webhook (GET /inbound lists active inbound connectors)
  for ($i = 0; $i -lt 30; $i++) { $r = Invoke-Http -Method GET -Url $IN -NoAuth; if ($r.Raw -match [regex]::Escape($ctx)) { Write-Host "  webhook $ctx active"; return }; Start-Sleep 2 }
  Write-Host "  webhook $ctx NOT listed by GET /inbound after 60s: $($r.Raw)" -ForegroundColor Yellow
}
function Complete-Hold($pi, $type = 'spike-s6-hold') {
  for ($i = 0; $i -lt 10; $i++) {
    $r = C8 '/v2/jobs/activation' @{ type = $type; maxJobsToActivate = 20; timeout = 3000; worker = 's6' }
    $job = @($r.Json.jobs) | Where-Object { [string]$_.processInstanceKey -eq $pi } | Select-Object -First 1
    if ($job) { C8 "/v2/jobs/$($job.jobKey)/completion" @{ variables = @{} } | Out-Null; return }
    Start-Sleep 2
  }
  throw "no $type job for $pi"
}
function Catch-State($pi) { $e = Get-Elements $pi { param($i) @($i | Where-Object { $_.elementId -eq 'WaitSignature' }).Count -gt 0 } 20
  ($e | Where-Object { $_.elementId -eq 'WaitSignature' } | Select-Object -First 1).state }
function Waiting($proc, $env) { $pi = Start-Instance $proc @{ envelopeId = $env }; Complete-Hold $pi
  Write-Host ("  pi={0} envelopeId={1} catch={2}" -f $pi, $env, (Catch-State $pi)); return $pi }
function Report($pi) { Start-Sleep 3; $v = Get-Vars $pi
  Write-Host ("  -> pi={0} state={1} catch={2} esignStatus={3} signerName={4} esignEventId={5}" -f $pi, (Get-InstanceState $pi), (Catch-State $pi), $v['esignStatus'], $v['signerName'], $v['esignEventId']) }

Wait-Webhook 'spike-esign-callback'; Wait-Webhook 'spike-esign-callback-nottl'; Wait-Webhook 'spike-b2b-application'
$P = 'spike-esign-callback'; $PN = 'spike-esign-callback-nottl'

Section '(a) correctly signed COMPLETED callback while instance waits'
$e1 = "ENV-$run-1"; $pi1 = Waiting 'spike-s6-esign' $e1
Post $P (Evt $e1 "EVT-$run-1") | Out-Null; Report $pi1

Section '(b) wrong signature / missing signature'
$e2 = "ENV-$run-2"; $pi2 = Waiting 'spike-s6-esign' $e2
Post $P (Evt $e2 "EVT-$run-2a") ('0' * 64) | Out-Null
Post $P (Evt $e2 "EVT-$run-2b") '' | Out-Null
Post $P (Evt $e2 "EVT-$run-2c") ('sha256=' + (Sign ((Evt $e2 "EVT-$run-2c") | ConvertTo-Json -Depth 10 -Compress))) | Out-Null
Report $pi2

Section '(c) activation condition false (status DECLINED): consumeUnmatchedEvents=false (TTL model) vs true (no-TTL model)'
Post $P (Evt $e2 "EVT-$run-2d" 'DECLINED') | Out-Null; Report $pi2
$e5 = "ENV-$run-5"; $pi5 = Waiting 'spike-s6-esign-nottl' $e5
Post $PN (Evt $e5 "EVT-$run-5a" 'DECLINED') | Out-Null; Report $pi5

Section '(d) same eventId twice'
Post $P (Evt $e2 "EVT-$run-2e") | Out-Null
Post $P (Evt $e2 "EVT-$run-2e") | Out-Null
Report $pi2
$e6 = "ENV-$run-6"; $pi6a = Waiting 'spike-s6-esign' $e6; $pi6b = Waiting 'spike-s6-esign' $e6   # two waiters, same key
Post $P (Evt $e6 "EVT-$run-6") | Out-Null; Post $P (Evt $e6 "EVT-$run-6") | Out-Null
Report $pi6a; Report $pi6b

Section '(e) EARLY callback before the catch event is reached: messageTtl=PT1M vs no messageTtl'
$e3 = "ENV-$run-3"; $pi3 = Start-Instance 'spike-s6-esign' @{ envelopeId = $e3 }
Post $P (Evt $e3 "EVT-$run-3") | Out-Null
Start-Sleep 5; Complete-Hold $pi3; Report $pi3
$e4 = "ENV-$run-4"; $pi4 = Start-Instance 'spike-s6-esign-nottl' @{ envelopeId = $e4 }
Post $PN (Evt $e4 "EVT-$run-4") | Out-Null
Start-Sleep 5; Complete-Hold $pi4; Report $pi4
Post $PN (Evt $e4 "EVT-$run-4b") | Out-Null; Report $pi4      # late re-send to release it
Post $PN (Evt $e5 "EVT-$run-5b") | Out-Null; Report $pi5      # release (c) waiter

Section 'Webhook START spike-b2b-application with API key (Authorization: Bearer <key>)'
$b2b = @{ applicationId = "B2B-$run"; applicant = @{ name = 'Solar Installers Ltd' }; capacityKw = 99 }
$ok = Invoke-Http -Method POST -Url "$IN/spike-b2b-application" -Body ($b2b | ConvertTo-Json -Compress) -Headers @{ Authorization = 'Bearer s6-b2b-test-key' } -NoAuth
Write-Host "  good key   -> HTTP $($ok.Status) $($ok.Raw)"
$bad = Invoke-Http -Method POST -Url "$IN/spike-b2b-application" -Body ($b2b | ConvertTo-Json -Compress) -Headers @{ Authorization = 'Bearer wrong' } -NoAuth
Write-Host "  wrong key  -> HTTP $($bad.Status) $($bad.Raw)"
$none = Invoke-Http -Method POST -Url "$IN/spike-b2b-application" -Body ($b2b | ConvertTo-Json -Compress) -NoAuth
Write-Host "  no header  -> HTTP $($none.Status) $($none.Raw)"
$noid = Invoke-Http -Method POST -Url "$IN/spike-b2b-application" -Body '{"foo":1}' -Headers @{ Authorization = 'Bearer s6-b2b-test-key' } -NoAuth
Write-Host "  no applicationId (activation false) -> HTTP $($noid.Status) $($noid.Raw)"
$vars = Search-Until '/v2/variables/search' @{ name = 'applicationId'; value = ('"B2B-' + $run + '"') } { param($i) $i.Count -gt 0 } 20
foreach ($pi in @($vars | ForEach-Object { [string]$_.processInstanceKey } | Sort-Object -Unique)) {
  $v = Get-Vars $pi; Write-Host ("  instance pi={0} vars: applicationId={1} applicantName={2} capacityKw={3} channel={4}" -f $pi, $v['applicationId'], $v['applicantName'], $v['capacityKw'], $v['channel'])
  Complete-Hold $pi 'spike-s6-b2b-hold'
}
